INSERT INTO `c_mapping_domain` VALUES ('102023012984550002', 'OSS', '阿里云OSS', '11', '主要用于系统图片等存储使用，请您购买阿里云OSS，获取一下参数配置，请注意前后空格，并且阿里云OSS账户授权oss存储权限', '2023-01-29 15:11:36', '0');
