INSERT INTO `c_mapping_domain` VALUES ('102023013087180022', 'TENCENT_SMS', '腾讯短信配置', '5', '腾讯短信配置\n开启验证码功能，搜索键为SMS_SEND_SWITCH的记录将值OFF改为ON\n键为 SMS_COMPANY 的值 腾讯为TENCENT', '2023-01-30 00:12:54', '0');
