INSERT INTO `contract_type_template` VALUES ('822021101935450005', '812021101902270004', '402021100552781023', '<p><span style=\"color: rgb(34, 34, 34); font-family: Arial, sans-serif; font-size: 14px; text-align: justify;\">个人借款合同甲方：________________(公司名称)乙方：________________(你的基本信息)甲、乙双方经协商，就乙方向甲方无息借款购买汽车事宜达成协议如下：1、借款金额：乙方向甲方借款金额为人民币____元。2、借款利息：甲方向乙方出借的款项在借款期限内不支付利息</span><br></p>', '2021-10-19 20:29:05', '0');
